export function applyPinnedGeometry(element, workspaceLayout) {
  const selectionRail = typeof workspaceLayout?.selectionRail === 'number'
    ? workspaceLayout.selectionRail
    : parseFloat(workspaceLayout?.selectionRail) || 48;

  element.style.setProperty('--selection-rail', `${selectionRail}px`);
  element.style.setProperty('--pinned-name-offset', `${selectionRail}px`);
}
